#!/bin/sh
# Run the tests2 C23 cases on every cross back end and compare each result
# with the expected output generated by the host gcc.
#
# Why this exists: two bugs (the arm64 bswap register field and _BitInt on
# targets where plain char is unsigned) passed every x86_64 check and every
# disassembly review, and only showed up when the output was actually
# executed.  Compiling for a target, or reading its disassembly, is not
# evidence that it works.
#
# Targets: i386 (runs natively, needs 32-bit crt and libtcc1), and arm, arm64,
# riscv64 (run under qemu-user with a sysroot).  Missing pieces are skipped
# rather than failing, so the script is safe to run anywhere.
#
# usage: tests/cross-run.sh [i386 arm64 arm riscv64 ...]
set -u

src=$(cd "$(dirname "$0")/.." && pwd)
t2=$src/tests/tests2
out=$src/.bench/cross-run
# -B wants the directory holding include/ and libtcc1.a
tccdir=${TCCDIR:-/opt/tinycc/lib/tcc}
[ -d "$tccdir/include" ] || tccdir=$src

tests="165_c23_spellings 168_c23_constexpr 172_c23_bitint
173_c23_fallthrough_place 174_c23_bitint_trunc 175_c23_bitint_incdec
176_c23_bitint_arith 177_c23_bitint_limits 178_c23_bitint_zero
179_c23_gnu_builtins 180_c23_builtin_object_size 181_c23_gnu_bit_builtins
182_c23_builtin_overflow 183_c23_has_c_attribute 184_c23_embed_params
185_c23_stdckdint 186_c23_bit_builtin_fold 187_c23_bitint_not_const
188_c23_bitint_var_width 189_c23_stddef_nullptr_t"

# These four expectations encode 64-bit sizes (sizeof(nullptr), (size_t)-1,
# clz of a 64-bit long).  A 32-bit target cannot match them, and when no
# 32-bit gcc is installed there is no oracle to re-check against, so they are
# reported instead of failed.  i386 and arm both differ in exactly these four.
word32="165_c23_spellings 180_c23_builtin_object_size 181_c23_gnu_bit_builtins
189_c23_stddef_nullptr_t"

mkdir -p "$out" || exit 1
cd "$t2" || exit 1
pass=0; fail=0; skip=0; abi=0; failed=""

for t in ${*:-i386 arm64 arm riscv64}; do
    # per-target settings: sysroot, runner, oracle compiler, extra link args
    pre=""; post=""; incs=""; sys=""; run=""; oracle=""
    case $t in
    i386)
        # tcc looks for crt in /usr/i686-linux-gnu/lib, which does not exist
        # here, and -nostdlib also drops libtcc1.a, so both are spelled out.
        [ -f /usr/lib32/crt1.o ] && [ -f /usr/lib32/libc.so ] || {
            echo "skip i386: no 32-bit crt/libc in /usr/lib32"; skip=$((skip+1)); continue; }
        pre="-nostdlib /usr/lib32/crt1.o /usr/lib32/crti.o"
        post="/usr/lib32/crtn.o $src/i386-libtcc1.a -L/usr/lib32 -lc"
        incs="-I/usr/include -I/usr/include/x86_64-linux-gnu"
        ;;
    arm64|arm|riscv64)
        # the sysroot directory uses the toolchain triple, not tcc's name
        case $t in
        arm64) sys=${SYSROOT:-/usr/aarch64-linux-gnu} ;;
        arm)   sys=${SYSROOT:-/usr/arm-linux-gnueabihf} ;;
        *)     sys=${SYSROOT:-/usr/riscv64-linux-gnu} ;;
        esac
        run=qemu-$t
        oracle=$(basename "$sys")-gcc
        command -v "$run" >/dev/null || { echo "skip $t: $run not installed"; skip=$((skip+1)); continue; }
        command -v "$oracle" >/dev/null || oracle=""
        [ -d "$sys/include" ] || { echo "skip $t: no sysroot at $sys"; skip=$((skip+1)); continue; }
        pre="-I$sys/include"
        post="$src/$t-libtcc1.a -L$sys/lib"
        incs=""
        ;;
    *)
        echo "unknown target $t"; exit 2 ;;
    esac
    [ -x "$src/$t-tcc" ] || { echo "skip $t: no $t-tcc (run make cross-$t)"; skip=$((skip+1)); continue; }

    echo "===== $t${sys:+ ($sys)}${oracle:+, oracle $oracle} ====="
    for n in $tests; do
        exe=$out/${n}_$t
        got=$out/${n}_$t.out
        exp=$n.expect
        [ -f "$exp" ] || continue
        rm -f "$exe" "$got"
        # keep the compiler's stderr: warnings are part of some expectations
        # shellcheck disable=SC2086
        "$src/$t-tcc" -B"$tccdir" $incs $pre -std=c23 "$n.c" $post \
            -o "$exe" > "$got" 2>&1
        if [ -x "$exe" ]; then
            if [ -n "$run" ]; then
                QEMU_LD_PREFIX=$sys "$run" "$exe" >> "$got" 2>&1
            else
                "$exe" >> "$got" 2>&1
            fi
        fi
        if cmp -s "$exp" "$got"; then
            pass=$((pass+1))
            continue
        fi
        # A 32-bit target cannot match an expectation generated on a 64-bit
        # host; re-check against that target's own gcc when there is one.
        if [ -n "$oracle" ]; then
            gexe=$out/${n}_$t.gcc
            ggot=$out/${n}_$t.gccout
            rm -f "$gexe" "$ggot"
            "$oracle" -w -std=c23 "$n.c" -o "$gexe" > "$ggot" 2>&1
            if [ -x "$gexe" ]; then
                QEMU_LD_PREFIX=$sys "$run" "$gexe" >> "$ggot" 2>&1
            fi
            if cmp -s "$ggot" "$got"; then
                pass=$((pass+1))
                echo "  $n: differs from the host expectation, matches $oracle"
                continue
            fi
        elif echo "$word32" | grep -qw "$n"; then
            abi=$((abi+1))
            echo "  $n: word-size difference, no 32-bit oracle to confirm"
            diff -u "$exp" "$got" | grep -E '^[-+][^-+]' | head -4 | sed 's/^/    /'
            continue
        fi
        fail=$((fail+1)); failed="$failed $t:$n"
        echo "  $n: output differs from $exp"
        diff -u "$exp" "$got" | sed -n '3,8p' | sed 's/^/    /'
    done
done

echo "----- pass=$pass word32=$abi fail=$fail skip=$skip -----"
[ -n "$failed" ] && echo "failed:$failed"
[ $fail -eq 0 ]
